export function circuitSvg(name) {
  const d = CIRCUITS[name];
  if (!d) return '';
  return `<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Tracé de circuit"><path d="${d}"/></svg>`;
}
